import{_ as e,o as r,a,b as d}from"./app.DKoEZOcr.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"Tensor API列表","link":"/api/SIMD-API/tensor_api/tensor_api_list"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/tensor_api_list.md","filePath":"api/SIMD-API/tensor_api/tensor_api_list.md","outlineHeaders":[{"level":2,"title":"基础数据结构","slug":"基础数据结构","link":"#基础数据结构"},{"level":2,"title":"Layout操作","slug":"Layout操作","link":"#Layout操作"},{"level":2,"title":"Algorithm","slug":"Algorithm","link":"#Algorithm"},{"level":2,"title":"数据搬运","slug":"数据搬运","link":"#数据搬运"},{"level":2,"title":"矩阵计算","slug":"矩阵计算","link":"#矩阵计算"},{"level":2,"title":"矢量计算接口","slug":"矢量计算接口","link":"#矢量计算接口"},{"level":2,"title":"工具接口","slug":"工具接口","link":"#工具接口"},{"level":2,"title":"废弃接口","slug":"废弃接口","link":"#废弃接口"}],"lastUpdated":1788319986000}'),o={name:"api/SIMD-API/tensor_api/tensor_api_list.md"};function _(c,t,l,h,m,u){return r(),a("div",null,[...t[0]||(t[0]=[d('<div><article class="markdown-body"><h1>Tensor API列表</h1><h2 id="基础数据结构">基础数据结构<a class="header-anchor" href="#基础数据结构">​</a></h2><p><strong>表1</strong> 基础数据结构接口列表</p><table><thead><tr><th>类型或接口名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="layout/layout.html">layout</a></td><td>使用Shape和Stride描述数据的逻辑形状及其内存布局。</td></tr><tr><td><a href="layout/shape.html">Shape</a></td><td>描述Tensor各维度的逻辑形状，支持普通整数和嵌套元组形式。</td></tr><tr><td><a href="layout/stride.html">Stride</a></td><td>描述Tensor各维度相邻元素在内存中的地址步长，支持普通整数和嵌套元组形式。</td></tr><tr><td><a href="layout/coord.html">Coord</a></td><td>描述Tensor在各维度上的逻辑坐标。</td></tr><tr><td><a href="tensor/tensor.html">global_tensor和local_tensor</a></td><td>分别描述Global Memory和片上Local Memory中的Tensor对象。</td></tr><tr><td><a href="tensor/pointer.html">Pointer</a></td><td>描述Tensor的访问地址及其对应的存储位置。</td></tr><tr><td><a href="layout/make_layout.html">make_layout</a></td><td>根据Shape和Stride构造普通Layout。</td></tr><tr><td><a href="layout/make_pattern_layout.html">make_pattern_layout</a></td><td>根据Layout Pattern、Shape和Stride构造带有排布类型信息的Layout。</td></tr><tr><td><a href="layout/make_frame_layout.html">make_frame_layout</a></td><td>根据卷积特征图或矩阵分形的Layout Pattern和形状参数构造Layout。</td></tr><tr><td><a href="layout/make_shape.html">make_shape</a></td><td>构造Shape对象。</td></tr><tr><td><a href="layout/make_stride.html">make_stride</a></td><td>构造Stride对象。</td></tr><tr><td><a href="layout/make_coord.html">make_coord</a></td><td>构造Coord对象。</td></tr><tr><td><a href="tensor/make_mem_ptr.html">make_mem_ptr</a></td><td>根据指针和存储位置构造Tensor API内存指针对象。</td></tr><tr><td><a href="tensor/make_tensor.html">make_tensor</a></td><td>将内存指针和Layout绑定，构造global_tensor或local_tensor。</td></tr><tr><td><a href="tensor/slice.html">slice</a></td><td>根据起始坐标和Shape或Layout描述创建原Tensor的子Tensor。</td></tr></tbody></table><h2 id="Layout操作">Layout操作<a class="header-anchor" href="#Layout操作">​</a></h2><p><strong>表2</strong> Layout操作接口列表</p><table><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="layout/capacity.html">capacity</a></td><td>获取Layout或指定子维度对应的实际内存容量。</td></tr><tr><td><a href="layout/coshape.html">coshape</a></td><td>在编译期获取Layout指定子维度的Shape结构。</td></tr><tr><td><a href="layout/cosize.html">cosize</a></td><td>在编译期获取Layout指定子维度的容量或元素数量。</td></tr><tr><td><a href="layout/crd2idx.html">crd2idx</a></td><td>将多维坐标按照Layout转换为线性内存索引。</td></tr><tr><td><a href="layout/get.html">get</a></td><td>获取元组中的指定元素，支持单个或多个编译期索引。</td></tr><tr><td><a href="layout/get_shape.html">get_shape</a></td><td>获取Layout的Shape或指定子维度的Shape。</td></tr><tr><td><a href="layout/get_stride.html">get_stride</a></td><td>获取Layout的Stride或指定子维度的Stride。</td></tr><tr><td><a href="layout/rank.html">rank</a></td><td>获取Layout的层级或维度信息。</td></tr><tr><td><a href="layout/select.html">select</a></td><td>按指定索引从Layout的Shape和Stride中选择子结构。</td></tr><tr><td><a href="layout/size.html">size</a></td><td>获取Layout的逻辑元素数量。</td></tr><tr><td><a href="layout/squeeze.html">squeeze</a></td><td>删除Shape顶层结构中指定的大小为1的维度。</td></tr></tbody></table><h2 id="Algorithm">Algorithm<a class="header-anchor" href="#Algorithm">​</a></h2><p><strong>表3</strong> Algorithm接口和类型列表</p><table><thead><tr><th>接口或类型名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="algorithm.html">Operation、Trait和Atom</a></td><td>介绍数据搬运和矩阵计算中Operation、Trait、Params和Atom的组合方式，以及<code>copy</code>和<code>mmad</code>统一调用入口。</td></tr></tbody></table><h2 id="数据搬运">数据搬运<a class="header-anchor" href="#数据搬运">​</a></h2><p><strong>表4</strong> 数据搬运通路和接口列表</p><table><thead><tr><th>数据通路或接口名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="reg_vector_compute/vector_compute_load/copy_gm_to_ub.html">Global Memory到Unified Buffer</a></td><td>使用<code>copy</code>将Global Memory中的数据搬运到Unified Buffer，支持坐标区域搬运。</td></tr><tr><td><a href="reg_vector_compute/vector_compute_store/copy_ub_to_gm.html">Unified Buffer到Global Memory</a></td><td>使用<code>copy</code>将Unified Buffer中的数据搬运到Global Memory，支持坐标区域搬运。</td></tr><tr><td><a href="matrix_compute/cube_compute_load/copy_gm_to_l1.html">Global Memory到L1 Buffer</a></td><td>使用<code>copy</code>将Global Memory中的数据搬运到L1 Buffer，并支持多种矩阵格式转换和Batch搬运。</td></tr><tr><td><a href="reg_vector_compute/vector_compute_load/copy_ub_to_l1.html">Unified Buffer到L1 Buffer</a></td><td>使用<code>copy</code>将Unified Buffer中的数据搬运到L1 Buffer。</td></tr><tr><td><a href="matrix_compute/cube_compute_load/copy_l1_to_ub.html">L1 Buffer到Unified Buffer</a></td><td>使用<code>copy</code>将L1 Buffer中的数据搬运到Unified Buffer。</td></tr><tr><td><a href="matrix_compute/cube_compute_load/copy_l1_to_l0a.html">L1 Buffer到L0A Buffer</a></td><td>使用<code>copy</code>将L1 Buffer中的左矩阵数据搬运到L0A Buffer，支持矩阵格式转换和卷积特征图搬运。</td></tr><tr><td><a href="matrix_compute/cube_compute_load/copy_l1_to_l0b.html">L1 Buffer到L0B Buffer</a></td><td>使用<code>copy</code>将L1 Buffer中的右矩阵数据搬运到L0B Buffer，支持矩阵格式转换和Batch搬运。</td></tr><tr><td><a href="matrix_compute/cube_compute_load/copy_l1_to_l0scalea.html">L1 Buffer到L0ScaleA Buffer</a></td><td>使用<code>copy</code>将L1 Buffer中的ScaleA数据搬运到L0ScaleA Buffer。</td></tr><tr><td><a href="matrix_compute/cube_compute_load/copy_l1_to_l0scaleb.html">L1 Buffer到L0ScaleB Buffer</a></td><td>使用<code>copy</code>将L1 Buffer中的ScaleB数据搬运到L0ScaleB Buffer。</td></tr><tr><td><a href="matrix_compute/cube_compute_load/copy_l1_to_biastable.html">L1 Buffer到BiasTable Buffer</a></td><td>使用<code>copy</code>将L1 Buffer中的Bias数据搬运到BiasTable Buffer。</td></tr><tr><td><a href="matrix_compute/cube_compute_load/copy_l1_to_fixbuf.html">L1 Buffer到Fixpipe Buffer</a></td><td>使用<code>copy</code>将L1 Buffer中的量化参数搬运到Fixpipe Buffer。</td></tr><tr><td><a href="matrix_compute/cube_compute_store/copy_l0c_to_gm.html">L0C Buffer到Global Memory</a></td><td>使用<code>copy</code>将L0C Buffer中的矩阵结果搬运到Global Memory，支持格式转换和量化输出。</td></tr><tr><td><a href="matrix_compute/cube_compute_store/copy_l0c_to_ub.html">L0C Buffer到Unified Buffer</a></td><td>使用<code>copy</code>将L0C Buffer中的矩阵结果搬运到Unified Buffer，支持格式转换和量化输出。</td></tr><tr><td><a href="matrix_compute/cube_compute_store/copy_l0c_to_l1.html">L0C Buffer到L1 Buffer</a></td><td>使用<code>copy</code>将L0C Buffer中的矩阵结果搬运到L1 Buffer。</td></tr><tr><td><a href="reg_vector_compute/vector_compute_load/copy_ub_to_ub.html">Unified Buffer内部搬运</a></td><td>使用<code>copy</code>完成Unified Buffer内部Tensor之间的数据搬运。</td></tr></tbody></table><h2 id="矩阵计算">矩阵计算<a class="header-anchor" href="#矩阵计算">​</a></h2><p><strong>表5</strong> 矩阵计算接口和特性列表</p><table><thead><tr><th>接口或主题</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="matrix_compute/overview.html">矩阵计算概述</a></td><td>介绍Tensor API矩阵计算的基本流程和接口组成。</td></tr><tr><td><a href="matrix_compute/cube_compute_fractal_intro.html">矩阵计算分形介绍</a></td><td>介绍矩阵计算中常用的数据分形格式及其Layout表达方式。</td></tr><tr><td><a href="matrix_compute/mmad_compute/mmad.html">mmad</a></td><td>使用L0A、L0B和可选Bias数据执行矩阵乘加计算，并将结果写入L0C。</td></tr><tr><td><a href="matrix_compute/mmad_compute_key_features/mmad_compute_key_features.html">mmad计算关键特性</a></td><td>介绍GEMV、HF32和unit_flag等矩阵乘加关键特性。</td></tr><tr><td><a href="matrix_compute/mmad_compute_key_features/gemv.html">GEMV</a></td><td>介绍M为1场景下的GEMV计算模式。</td></tr><tr><td><a href="matrix_compute/mmad_compute_key_features/hf32.html">HF32</a></td><td>介绍矩阵计算中的HF32精度模式。</td></tr><tr><td><a href="matrix_compute/mmad_compute_key_features/unit_flag.html">unit_flag</a></td><td>介绍mmad与后续矩阵数据搬出之间的细粒度并行控制。</td></tr><tr><td><a href="matrix_compute/mmad_compute_aux_config.html">mmad计算辅助配置</a></td><td>列出mmad计算所需的C API辅助配置接口。</td></tr><tr><td><a href="matrix_compute/cube_compute_load/overall_description.html">矩阵计算搬入总体说明</a></td><td>说明矩阵数据从Global Memory或L1 Buffer搬入各级矩阵计算Buffer的通路。</td></tr><tr><td><a href="matrix_compute/cube_compute_store/overall_description.html">矩阵计算搬出总体说明</a></td><td>说明矩阵结果从L0C Buffer搬出到Global Memory、Unified Buffer或L1 Buffer的通路。</td></tr><tr><td><a href="matrix_compute/cube_store_key_features/cube_store_key_features.html">矩阵搬出关键特性</a></td><td>介绍随路量化、随路ReLU、通道拆分、通道合并、Batch搬运和双目标模式。</td></tr><tr><td><a href="matrix_compute/cube_store_key_features/quant_pre.html">随路量化</a></td><td>介绍矩阵结果搬出过程中的随路量化能力。</td></tr><tr><td><a href="matrix_compute/cube_store_key_features/relu_pre.html">随路ReLU</a></td><td>介绍矩阵结果搬出过程中的随路ReLU能力。</td></tr><tr><td><a href="matrix_compute/cube_store_key_features/f32_channel_split.html">F32 Channel Split</a></td><td>介绍F32结果搬出时的通道拆分能力。</td></tr><tr><td><a href="matrix_compute/cube_store_key_features/int8_channel_merge.html">Int8 Channel Merge</a></td><td>介绍Int8结果搬出时的通道合并能力。</td></tr><tr><td><a href="matrix_compute/cube_store_key_features/batch_copy.html">Batch搬运</a></td><td>介绍矩阵结果的多Batch搬出能力。</td></tr><tr><td><a href="matrix_compute/cube_store_key_features/l0c_to_ub_dual_dst.html">L0C到Unified Buffer双目标模式</a></td><td>介绍L0C到Unified Buffer的双目标搬出模式。</td></tr></tbody></table><h2 id="矢量计算接口">矢量计算接口<a class="header-anchor" href="#矢量计算接口">​</a></h2><p><strong>表6</strong> 矢量计算接口列表</p><table><thead><tr><th>接口或类型名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="reg_vector_compute/reg_tensor/reg_tensor.html">reg_tensor</a></td><td>封装矢量数据寄存器及其掩码寄存器，用于寄存器数据计算。</td></tr><tr><td><a href="reg_vector_compute/reg_tensor/reg_pair.html">reg_pair</a></td><td>保存两个元素类型相同的<code>reg_tensor</code>，用于具有双结果的寄存器接口。</td></tr><tr><td><a href="reg_vector_compute/mask_reg_compute/all_mask.html">all_mask</a></td><td>创建与指定元素类型位宽匹配的全有效Mask寄存器。</td></tr><tr><td><a href="reg_vector_compute/mask_reg_compute/make_mask.html">make_mask</a></td><td>根据Mask模式和数据元素宽度创建Mask寄存器。</td></tr><tr><td><a href="reg_vector_compute/mask_reg_compute/none_mask.html">none_mask</a></td><td>创建与指定元素类型位宽匹配的全无效Mask寄存器。</td></tr><tr><td><a href="reg_vector_compute/mask_reg_compute/update_mask.html">update_mask</a></td><td>根据剩余待处理元素数生成有效位Mask，并更新剩余元素数量。</td></tr><tr><td><a href="reg_vector_compute/mask_reg_compute/deinterleave.html">deinterleave（掩码寄存器解交织）</a></td><td>将两个Mask寄存器按指定元素宽度解交织，返回偶数组和奇数组结果。</td></tr><tr><td><a href="reg_vector_compute/reg_data_load/load.html">load</a></td><td>将Unified Buffer中的数据搬入<code>reg_tensor</code>，支持多种数据排列方式。</td></tr><tr><td><a href="reg_vector_compute/reg_data_load/load_broadcast.html">load_broadcast</a></td><td>从Unified Buffer搬入数据，并按指定模式广播到<code>reg_tensor</code>。</td></tr><tr><td><a href="reg_vector_compute/reg_data_store/store.html">store</a></td><td>将<code>reg_tensor</code>中的数据搬出到Unified Buffer，支持多种数据排列方式。</td></tr><tr><td><a href="reg_vector_compute/type_conversion/cast.html">cast</a></td><td>转换寄存器数据类型，支持配置数据排布、舍入和饱和模式。</td></tr><tr><td><a href="reg_vector_compute/type_conversion/trunc.html">trunc</a></td><td>将Mask选中的浮点元素向零取整，并保留原数据类型。</td></tr><tr><td><a href="reg_vector_compute/basic_arithmetic/log.html">log</a></td><td>对源操作数中的有效元素逐元素计算自然对数。</td></tr><tr><td><a href="reg_vector_compute/basic_arithmetic/max.html">max</a></td><td>对两个源操作数逐元素计算最大值。</td></tr><tr><td><a href="reg_vector_compute/basic_arithmetic/operator_add.html">operator+</a></td><td>对两个源操作数逐元素执行加法计算。</td></tr><tr><td><a href="reg_vector_compute/basic_arithmetic/operator_sub.html">operator-</a></td><td>对两个源操作数逐元素执行减法计算。</td></tr><tr><td><a href="reg_vector_compute/basic_arithmetic/operator_mul.html">operator*</a></td><td>对两个源操作数逐元素执行乘法计算。</td></tr><tr><td><a href="reg_vector_compute/logical_compute/or.html">or</a></td><td>对两个源操作数逐元素执行按位或计算。</td></tr><tr><td><a href="reg_vector_compute/compare_and_select/compare_and_select.html">选择与比较</a></td><td>根据mask的比特位值，从源操作数src0、src1中选择元素，得到目的操作数。</td></tr><tr><td><a href="reg_vector_compute/compare_and_select/select.html">select</a></td><td>根据条件Mask从两个源寄存器中逐元素选择数据。</td></tr><tr><td><a href="reg_vector_compute/data_padding/data_padding.html">数据填充</a></td><td>根据mask将源操作数src的最低位元素或者一个scalar操作数填充到目的操作数。</td></tr><tr><td><a href="reg_vector_compute/data_padding/fill.html">fill</a></td><td>将标量或源寄存器最低位元素广播并填充到目的寄存器。</td></tr><tr><td><a href="reg_vector_compute/data_reorder/data_reorder.html">数据重排</a></td><td>给定源操作数src0和src1，将src0和src1中的元素解交织存入结果操作数。</td></tr><tr><td><a href="reg_vector_compute/data_reorder/deinterleave.html">deinterleave（数据寄存器解交织）</a></td><td>将两个源寄存器中的元素解交织到两个结果寄存器。</td></tr></tbody></table><h2 id="工具接口">工具接口<a class="header-anchor" href="#工具接口">​</a></h2><p><strong>表7</strong> 工具接口列表</p><table><thead><tr><th>接口或类型名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="utils/compile_time_integer_aliases.html">编译期整型别名</a></td><td>提供用于表达编译期整数值的类型别名。</td></tr><tr><td><a href="utils/dimension_keep_mark.html">维度保留标记</a></td><td>提供用于标记维度保留行为的类型和常量。</td></tr><tr><td><a href="utils/get_layout_pattern.html">get_layout_pattern</a></td><td>从Layout类型中提取Layout Pattern类型信息。</td></tr><tr><td><a href="utils/type_traits.html">类型判断与提取工具</a></td><td>提供Layout、Tensor、Coord、Shape、量化参数等类型判断工具。</td></tr></tbody></table><h2 id="废弃接口">废弃接口<a class="header-anchor" href="#废弃接口">​</a></h2><p><strong>表8</strong> 废弃接口列表</p><table><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="deprecated_interface/deprecated_interface.html">废弃接口说明</a></td><td>汇总Tensor API中用于兼容旧版大驼峰命名的废弃接口。</td></tr><tr><td><a href="deprecated_interface/layout_capacity_deprecated.html">layout::Capacity</a></td><td>旧版Layout容量查询接口。</td></tr><tr><td><a href="deprecated_interface/layout_shape_deprecated.html">layout::Shape</a></td><td>旧版Layout Shape查询接口。</td></tr><tr><td><a href="deprecated_interface/layout_stride_deprecated.html">layout::Stride</a></td><td>旧版Layout Stride查询接口。</td></tr><tr><td><a href="deprecated_interface/layout_rank_deprecated.html">layout::Rank</a></td><td>旧版Layout层级查询接口。</td></tr><tr><td><a href="deprecated_interface/layout_size_deprecated.html">layout::Size</a></td><td>旧版Layout逻辑元素数量查询接口。</td></tr><tr><td><a href="deprecated_interface/layout_get_deprecated.html">layout::Get</a></td><td>旧版Layout元素获取接口。</td></tr><tr><td><a href="deprecated_interface/tensor_tensor_deprecated.html">base_tensor::Tensor</a></td><td>旧版Tensor对象访问接口。</td></tr><tr><td><a href="deprecated_interface/tensor_engine_deprecated.html">base_tensor::Engine</a></td><td>旧版Tensor Engine访问接口。</td></tr><tr><td><a href="deprecated_interface/tensor_layout_deprecated.html">base_tensor::Layout</a></td><td>旧版Tensor Layout访问接口。</td></tr><tr><td><a href="deprecated_interface/tensor_data_deprecated.html">base_tensor::Data</a></td><td>旧版Tensor数据地址访问接口。</td></tr><tr><td><a href="deprecated_interface/tensor_shape_deprecated.html">base_tensor::Shape</a></td><td>旧版Tensor Shape访问接口。</td></tr><tr><td><a href="deprecated_interface/tensor_stride_deprecated.html">base_tensor::Stride</a></td><td>旧版Tensor Stride访问接口。</td></tr><tr><td><a href="deprecated_interface/tensor_size_deprecated.html">base_tensor::Size</a></td><td>旧版Tensor逻辑元素数量查询接口。</td></tr><tr><td><a href="deprecated_interface/tensor_capacity_deprecated.html">base_tensor::Capacity</a></td><td>旧版Tensor容量查询接口。</td></tr><tr><td><a href="deprecated_interface/tensor_slice_deprecated.html">base_tensor::Slice</a></td><td>旧版Tensor切片接口。</td></tr><tr><td><a href="deprecated_interface/set_l2_cache_hint_deprecated.html">global_tensor::SetL2CacheHint</a></td><td>旧版Global Tensor L2 Cache配置接口。</td></tr></tbody></table></article></div>',1)])])}const i=e(o,[["render",_]]);export{s as __pageData,i as default};
